spec fn no_factor_below(candidate: u64, f: u64) -> bool {
    forall|factor: u64| 1 < factor && factor < f ==> !#[trigger] given::divides(factor, candidate)
}

#[effects(pure)]
#[uses(greater_than_one, prime_result, no_factor_below, given::divides, given::is_prime)]
fn test_prime(candidate: u64) -> (r: bool)
    requires greater_than_one(candidate),
    ensures prime_result(candidate, r),
{
    let mut f: u64 = 2;
    let mut prime: bool = true;
    while f < candidate
        invariant
            greater_than_one(candidate),
            2 <= f,
            f <= candidate,
            prime ==> no_factor_below(candidate, f),
            !prime ==> !given::is_prime(candidate),
        decreases candidate - f,
    {
        if candidate % f == 0 {
            prime = false;
            f = candidate;
        } else {
            f = f + 1;
        }
    }
    prime
}

#[effects(pure)]
