}

#[effects(pure)]
#[uses(valid_input, is_max_diff, in_bounds, idx_ok, upper, lower)]
fn max_difference(arr: &[i64]) -> (r: i64)
    requires valid_input(arr),
    ensures is_max_diff(arr, r),
{
    let mut mx: i64 = arr[0];
    let mut mn: i64 = arr[0];
    let mut k: usize = 1;
    while k < arr.len()
        invariant
            valid_input(arr),
            idx_ok(arr, k),
            in_bounds(mx),
            in_bounds(mn),
            upper(arr, k, mx),
            lower(arr, k, mn),
        decreases arr.len() - k,
    {
        let v: i64 = arr[k];
        if v > mx {
            mx = v;
        }
        if v < mn {
            mn = v;
        }
        k = k + 1;
    }
    mx - mn
}

