            invariant n == nums.len(), n <= 2500, i < n, j <= i, dp_bounded(dp), cur_bounded(cur, j),
            decreases i - j,
        {
            if nums[j] < nums[i] {
                let cand: i64 = dp[j] + 1;
                if cand > cur {
                    cur = cand;
                }
            }
            j = j + 1;
        }
        dp[i] = cur;
        if cur > best {
            best = cur;
        }
        i = i + 1;
    }
    best
}

spec fn valid_input(n: i64) -> bool { n >= 0 && n <= 2147483647 }

spec fn is_last_digit(n: i64, r: i64) -> bool { 0 <= r && r < 10 && r == n % 10 }

#[effects(pure)]
#[uses(valid_input, is_last_digit)]
fn last_digit(n: i64) -> (r: i64)
    requires valid_input(n),
    ensures is_last_digit(n, r),
{
    n % 10
}

spec fn valid_prices(cost_price: i64, selling_price: i64) -> bool {
    0 <= cost_price && cost_price <= 2147483647 && 0 <= selling_price && selling_price <= 2147483647
}

spec fn is_loss(cost_price: i64, selling_price: i64, r: i64) -> bool {
    (cost_price > selling_price && r == cost_price - selling_price)
    || (cost_price <= selling_price && r == 0)
}

#[effects(pure)]
#[uses(valid_prices, is_loss)]
fn calculate_loss(cost_price: i64, selling_price: i64) -> (r: i64)
    requires valid_prices(cost_price, selling_price),
    ensures is_loss(cost_price, selling_price, r),
{
    if cost_price > selling_price {
        cost_price - selling_price
    } else {
        0
    }
}

spec fn valid_month(month: i64) -> bool { 1 <= month && month <= 12 }

spec fn thirty_days_result(month: i64, r: bool) -> bool {
    r == (month == 4 || month == 6 || month == 9 || month == 11)
}

#[effects(pure)]
#[uses(valid_month, thirty_days_result)]
fn is_month_with_30_days(month: i64) -> (r: bool)
    requires valid_month(month),
    ensures thirty_days_result(month, r),
{
    month == 4 || month == 6 || month == 9 || month == 11
}

spec fn non_empty(a: &[i64]) -> bool { a.len() > 0 }

spec fn is_max_of(a: &[i64], r: i64) -> bool {
    (exists|i: usize| i < a.len() && #[trigger] a[i] == r)
    && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= r)
}

spec fn prefix_max(a: &[i64], k: usize, m: i64) -> bool {
    1 <= k && k <= a.len()
    && (exists|i: usize| i < k && #[trigger] a[i] == m)
    && (forall|j: usize| j < k ==> #[trigger] a[j] <= m)
}

#[effects(pure)]
#[uses(non_empty, is_max_of, prefix_max)]
fn max_of_list(lst: &[i64]) -> (r: i64)
    requires non_empty(lst),
    ensures is_max_of(lst, r),
{
    let mut m: i64 = lst[0];
    let mut k: usize = 1;
    while k < lst.len()
        invariant prefix_max(lst, k, m),
        decreases lst.len() - k,
    {
        if lst[k] > m {
            m = lst[k];
        }
        k = k + 1;
    }
    m
}

