spec fn true_when_equal(a: i64, b: i64, r: bool) -> bool { a == b ==> r == true }

spec fn false_when_different(a: i64, b: i64, r: bool) -> bool { a != b ==> r == false }

#[effects(pure)]
#[uses(true_when_equal, false_when_different)]
fn compare(a: i64, b: i64) -> (r: bool)
    ensures true_when_equal(a, b, r), false_when_different(a, b, r),
{
    a == b
}
